 *
 * Workflow:
 *
 * 1. Register a new todo user via /auth/user/join, obtain authentication token and
 *    user id.
 * 2. Call GET /todo/user/users/{userId}/sessions/{sessionId} as that user to
 *    retrieve session details.
 * 3. Validate that all ITodoUserSession fields are present and match the
 *    authorized user/session context (userId matches, etc).
 * 4. (Edge) If implemented, ensure unauthorized retrieval by another user is
 *    forbidden (not in this function).
 */
export async function test_api_todo_user_session_detail_retrieval_by_owner(
  connection: api.IConnection,
) {
  // 1. Register new todo user (and create initial authenticated session)
  const userRequest = {
    email: typia.random<
      string & tags.MinLength<3> & tags.MaxLength<256> & tags.Format<"email">
    >(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    // Optionally supply IP
    ip: RandomGenerator.pick([
      typia.random<string & tags.Format<"ipv4">>(),
      typia.random<string & tags.Format<"ipv6">>(),
      null,
    ]),
  } satisfies ITodoUser.ICreate;

  const authorized: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userRequest },
  );
  typia.assert(authorized);

  // 2. The session created by join should now exist - extract session info from token if possible.
  // There's no explicit session id in the join response. A safe pattern is to decode the JWT, or instead
  // query the session detail endpoint with the user's current session (should be their own valid session).
  // Here, test if we can fetch session by using a valid uuid as sessionId that matches user's session.
  // However, lacking direct sessionId - this test is written for the scenario that exposes the sessionId elsewhere.
  // To fit the prompt, we'll assume that after join, the user's current session is retrievable with the correct sessionId
  // and that sessionId can be obtained as a property of the authenticated token/session (if not, this must be adapted).

  // Assumption: Access token (authorized.token.access) is sufficient for user to call their own session info via /todo/user/users/{userId}/sessions/{sessionId}
  // However, we need the sessionId. Typically, this would be provided in a session management endpoint or as a field in a session list.
  // Since we have no session listing endpoint here, we'll generate a plausible sessionId for a positive result check.
  // Instead, choose this approach: Treat this E2E test as a smoke test for endpoint permission/access flow and response type.
  // This test will use a random string & tags.Format<"uuid"> as the sessionId - in a real scenario, this would be returned or discoverable from session management endpoints.

  // In real test environments, system should be capable to list/get sessionId for the user's current session; for now, smoke test the endpoint shape.
  const userId = authorized.id;
  // In the absence of an API for obtaining sessionId, this test cannot fully verify the round trip of retrieving the session using a real sessionId created. So, get random.
  const sessionId = typia.random<string & tags.Format<"uuid">>();
  const session: ITodoUserSession =
    await api.functional.todo.user.users.sessions.at(connection, {
      userId,
      sessionId,
    });
  typia.assert(session);
  // Validate that todo_user_id in the result matches this user's id
  TestValidator.equals("session owner's userId", session.todo_user_id, userId);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate that an authenticated user can successfully terminate their own
 * session.
 *
 * 1. Register (join) a new user account, capturing issued token/session (from
 *    IAuthorized.token fields)
 * 2. Use issued access token context to call DELETE
 *    /todo/user/users/{userId}/sessions/{sessionId} for current session
 * 3. Validate that deletion succeeds (no error thrown)
 * 4. Attempt to call session termination endpoint again using the same access
 *    token (should be rejected, since session is terminated)
 * 5. Assert that access is denied for the deleted/terminated session (expected
 *    error)
 */
export async function test_api_todo_user_session_termination_by_owner(
  connection: api.IConnection,
) {
  // 1. Register / join a new user
  const registerBody = {
    email: typia.random<
      string & tags.MinLength<3> & tags.MaxLength<256> & tags.Format<"email">
    >(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/landing",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies ITodoUser.ICreate;
  const auth: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: registerBody,
    },
  );
  typia.assert(auth);

  // Note: There's no explicit sessionId UUID in auth/token, so use a random UUID for demonstration;
  // in a real implementation, sessionId should come from session creation response, not random.
  const sessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. DELETE the (simulated) user session (self-logout)
  await api.functional.todo.user.users.sessions.erase(connection, {
    userId: auth.id,
    sessionId,
  });

  // 3. Confirm access is denied by trying to delete again with same session
  await TestValidator.error(
    "deleted session cannot terminate again (must deny)",
    async () => {
      await api.functional.todo.user.users.sessions.erase(connection, {
        userId: auth.id,
        sessionId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate that a user can successfully delete their own todo item.
 *
 * 1. Register a new user for ownership context via /auth/user/join, capturing the
 *    resulting user information.
 * 2. As this user, create a new todo item via POST /todo/user/todos, capturing the
 *    returned todo id.
 * 3. Issue DELETE /todo/user/todos/{todoId} using the same authentication to
 *    delete the todo.
 * 4. Confirm the DELETE succeeds (does not throw). Optionally, attempt a re-DELETE
 *    to confirm it fails (demonstrates irreversibility).
 * 5. (If GET by ID exists) Confirm the todo is no longer retrievable; otherwise,
 *    this step is omitted due to unavailable API.
 *
 * The intent is to fully verify that deletion is possible only by the owner
 * and, once deleted, the todo is irreversibly removed.
 */
export async function test_api_todo_deletion_by_owner(
  connection: api.IConnection,
) {
  // 1. Register a user to provide authentication and ownership context
  const joinBody = {
    email: typia.random<
      string & tags.MinLength<3> & tags.MaxLength<256> & tags.Format<"email">
    >(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    href: "https://localhost/register",
    referrer: "https://localhost/login",
  } satisfies ITodoUser.ICreate;
  const user: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinBody },
  );
  typia.assert(user);
  // (SDK updates connection.headers.Authorization automatically)

  // 2. As this user, create a todo item
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    status: "incomplete",
  } satisfies ITodoTodo.ICreate;
  const todo: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    { body: todoCreateBody },
  );
  typia.assert(todo);
  TestValidator.equals("created user matches owner", todo.user.id, user.id);

  // 3. Delete the todo as owner
  await api.functional.todo.user.todos.erase(connection, { todoId: todo.id });

  // 4. No GET API provided, so we cannot check retrievability directly.
  // (In a real test, would attempt to GET and expect 404, but API is not given.)

  // 5. (Optional extra) Re-deleting should result in error. TestValidator.error for hard deletion.
  await TestValidator.error(
    "re-delete should fail: todo already deleted",
    async () => {
      await api.functional.todo.user.todos.erase(connection, {
        todoId: todo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test refreshing user authentication tokens (JWT access/refresh tokens) for a
 * valid, active session.
 *
 * 1. Register a new user using ITodoUser.ICreate and obtain initial tokens
 * 2. Call /auth/user/refresh with the initial refresh token, expecting a fresh
 *    ITodoUser.IAuthorized response
 * 3. Check that the returned token properties (access, refresh, expired_at,
 *    refreshable_until) are present and well-formed
 * 4. Confirm the user id/email does not change and timestamps are updated
 *    reasonably (tokens are rotated)
 * 5. Confirm the new refresh token is different from the old one
 * 6. Attempt to reuse the original (now-invalidated) refresh token with
 *    /auth/user/refresh, expecting error
 */
export async function test_api_user_token_refresh_valid_session(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const userEmail: string = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<256> & tags.Format<"email">
  >();
  const userPassword: string = typia.random<
    string & tags.MinLength<8> & tags.MaxLength<128>
  >();
  const registrationBody = {
    email: userEmail,
    password: userPassword,
    ip: null,
    href: "https://test.local/register",
    referrer: "https://test.local/login",
  } satisfies ITodoUser.ICreate;
  const initialAuth: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: registrationBody });
  typia.assert(initialAuth);
  TestValidator.equals(
    "registered user email matches",
    initialAuth.email,
    userEmail,
  );
  // 2. Submit refresh token for valid session
  const refreshBody = {
    refresh_token: initialAuth.token.refresh,
  } satisfies ITodoUser.IRefresh;
  const refreshedAuth: ITodoUser.IAuthorized =
    await api.functional.auth.user.refresh(connection, { body: refreshBody });
  typia.assert(refreshedAuth);
  // 3. Validate token output structure
  TestValidator.predicate(
    "access token present",
    refreshedAuth.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token present",
    refreshedAuth.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token expiry is ISO string",
    typeof refreshedAuth.token.expired_at === "string" &&
      refreshedAuth.token.expired_at.endsWith("Z"),
  );
  TestValidator.predicate(
    "refreshable until is ISO string",
    typeof refreshedAuth.token.refreshable_until === "string" &&
      refreshedAuth.token.refreshable_until.endsWith("Z"),
  );
  // 4. User id/email do not change
  TestValidator.equals(
    "user id does not change",
    refreshedAuth.id,
    initialAuth.id,
  );
  TestValidator.equals(
    "user email does not change",
    refreshedAuth.email,
    initialAuth.email,
  );
  // 5. New token values are distinct
  TestValidator.notEquals(
    "refresh token rotated",
    refreshedAuth.token.refresh,
    initialAuth.token.refresh,
  );
  TestValidator.notEquals(
    "access token rotated",
    refreshedAuth.token.access,
    initialAuth.token.access,
  );
  // 6. Attempt to reuse old refresh token and expect error
  await TestValidator.error("old refresh token cannot be reused", async () => {
    await api.functional.auth.user.refresh(connection, { body: refreshBody });
  });
}

